import { describe, it, expect, vi } from 'vitest'
import { NextRequest } from 'next/server'
import { middleware } from './middleware'
import defaultMiddleware from './middleware'

describe('middleware', () => {
  it('should be exported as named and default export', () => {
    expect(middleware).toBeDefined()
    expect(defaultMiddleware).toBeDefined()
    expect(middleware).toBe(defaultMiddleware)
  })

  it('should log the request pathname to the console', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {})
    const request = new NextRequest('http://localhost:3000/test/path')

    middleware(request)

    expect(consoleSpy).toHaveBeenCalledWith('/test/path')
    consoleSpy.mockRestore()
  })

  it('should log pathname when URL has query parameters', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {})
    const request = new NextRequest('http://localhost:3000/api/users?query=123')

    middleware(request)

    expect(consoleSpy).toHaveBeenCalledWith('/api/users')
    consoleSpy.mockRestore()
  })

  it('should add custom header X-Request-Id with unique values to responses', () => {
    const request1 = new NextRequest('http://localhost:3000/first')
    const request2 = new NextRequest('http://localhost:3000/second')

    const response1 = middleware(request1)
    const response2 = middleware(request2)

    const requestId1 = response1.headers.get('X-Request-Id')
    const requestId2 = response2.headers.get('X-Request-Id')

    expect(requestId1).toBeTruthy()
    expect(requestId2).toBeTruthy()
    expect(requestId1).not.toBe(requestId2)

    // Check UUID format: 8-4-4-4-12 hex chars
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    expect(requestId1).toMatch(uuidRegex)
    expect(requestId2).toMatch(uuidRegex)
  })

  it('works with standard Request object if passed', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {})
    const request = new Request('http://localhost:3000/standard-request') as any

    const response = middleware(request)
    expect(consoleSpy).toHaveBeenCalledWith('/standard-request')
    expect(response.headers.get('X-Request-Id')).toBeTruthy()
    consoleSpy.mockRestore()
  })
})

